package registry

import "testing"

func TestReady(t *testing.T) {
	if !Ready() {
		t.Fatal("baseline not ready")
	}
}

// Package registry 是本地数字藏品登记与流转的本地基线。
package registry

// Ready 表示基线可以运行。
func Ready() bool { return true }

